def get_pings(self) -> list[ServicePing]:
    """
    Return all services that have defined a *ping* and bind them to this
    container.

    Returns:
        A list of services that have registered a ping callable.
    """
    pings = []
    seen_types = set()

    # Check local registry first (since it shadows)
    if self._lazy_local_registry is not None:
        for svc_type, rs in self._lazy_local_registry._services.items():
            if svc_type not in seen_types:
                if rs.ping is not None:
                    pings.append(
                        ServicePing(
                            rs.name,
                            iscoroutinefunction(rs.ping),
                            rs.svc_type,
                            rs.ping,
                            self,
                        )
                    )
                seen_types.add(svc_type)

    # Check registry
    for svc_type, rs in self.registry._services.items():
        if svc_type not in seen_types:
            if rs.ping is not None:
                pings.append(
                    ServicePing(
                        rs.name,
                        iscoroutinefunction(rs.ping),
                        rs.svc_type,
                        rs.ping,
                        self,
                    )
                )
            seen_types.add(svc_type)

    return pings

